import redis
def val(r,k,t):
    if t=='string': return r.get(k)
    if t=='list': return r.lrange(k,0,-1)
    if t=='set': return sorted(r.smembers(k))
    if t=='zset': return r.zrange(k,0,-1,withscores=True)
    if t=='hash': return sorted(r.hgetall(k).items())
    if t=='stream':
        groups=r.xinfo_groups(k)
        g=[(x['name'],x['last-delivered-id'],x.get('entries-read'),x['pending'],
            r.xpending_range(k,x['name'],'-','+',100000) and [(p['message_id'],p['consumer'],p['times_delivered']) for p in r.xpending_range(k,x['name'],'-','+',100000)],
            sorted((c['name'],c['pending']) for c in r.xinfo_consumers(k,x['name']))) for x in groups]
        info=r.xinfo_stream(k)
        return (r.xrange(k),g,info['last-generated-id'],info.get('max-deleted-entry-id'),info.get('entries-added'))
    return ('?',t)
bad=0; n=0; types={}
for db in range(16):
    a=redis.Redis(port=6379,db=db); b=redis.Redis(port=6380,db=db)
    ka=set(a.scan_iter(count=1000)); kb=set(b.scan_iter(count=1000))
    if ka!=kb: print('db',db,'keyset diff',len(ka-kb),len(kb-ka)); bad+=1
    for k in ka&kb:
        n+=1
        t=a.type(k).decode(); types[t]=types.get(t,0)+1
        if b.type(k).decode()!=t: print('type',db,k); bad+=1; continue
        if val(a,k,t)!=val(b,k,t): print('val',db,k,t); bad+=1
        ta,tb=a.pttl(k),b.pttl(k)
        if (ta<0)!=(tb<0) or abs(ta-tb)>5000: print('ttl',db,k,ta,tb); bad+=1
print('checked',n,'bad',bad,types)
EOF
